arrayPipelines.data:
[
	{ $match: {{ pulse_filter_js.getMatchQuery() }}},
	 { $group: {
	 _id: null,
	 total_calls:        { $sum: 1 },
	total_active_secs:  { $sum: { $ifNull: ["$assist_stats.billing_meta.total_active_seconds", "$usage_transaction.total_active_seconds", 0] } },
total_nudges:       { $sum: { $ifNull: ["$assist_stats.nudges_delivered_total", 0] } },
total_transactions: { $sum: { $ifNull: ["$usage_transaction.transaction_value", 0] } }
} },
{ $project: {
	total_calls: 1,
	total_active_secs: 1,
	total_nudges: 1,
	total_transactions: 1
} }
]

